const item = (id, prompt, options, correct, explanation, evidence) =>
  ({ id, prompt, options, correct, explanation, ...(evidence ? { evidence } : {}) });

const bilingual = (code, items) => ['es', 'ca'].map((language, locale) => ({
  code,
  language,
  questions: Object.fromEntries(items.map(question => [question.id, {
    prompt: question.prompt[locale],
    options: question.options.map(option => option[locale]),
    correct: question.correct,
    explanation: question.explanation[locale],
    ...(question.evidence ? { evidence: question.evidence[locale] } : {}),
  }])),
}));

